// Regenerates src/lib/academy/leaves/index.ts from the leaf JSON files beside it.
import { readdirSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const dir = fileURLToPath(new URL("../src/lib/academy/leaves/", import.meta.url));
const files = readdirSync(dir).filter((f) => /^\d\d\.json$/.test(f)).sort();
const lines = [
  "// Generated by scripts/academy-leaves-index.mjs. Do not edit by hand.",
  ...files.map((f) => `import leaf${f.slice(0, 2)} from "./${f}";`),
  "",
  `export const LEAF_FILES = [${files.map((f) => `leaf${f.slice(0, 2)}`).join(", ")}];`,
  "",
];
writeFileSync(dir + "index.ts", lines.join("\n"));
console.log(`${files.length} leaves indexed`);
